k = input(7, "K Neighbors", 1, 15, 1)
featureLookback = input(20, "Feature Lookback", 5, 40, 1)
neighbourPool = input(200, "Neighbour Pool", 50, 400, 10)
marginThreshold = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disagreementThreshold = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.01)
show3D = input(true, "Show 3D")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

safeClose1 = close[1]
if safeClose1 == 0 { safeClose1 := close }
r = (close - safeClose1) / safeClose1
rng = (high - low) / close

var warmM = 0.0
var warmD = 1.0
var bullCache = 0
var bearCache = 0

effN = neighbourPool
if bar_index < neighbourPool { effN := bar_index }
if effN < 5 { effN := 5 }

meanR = 0.0
meanG = 0.0
p = 0
while p < effN {
    meanR := meanR + r[p]
    meanG := meanG + rng[p]
    p := p + 1
}
meanR := meanR / effN
meanG := meanG / effN

varR = 0.0
varG = 0.0
p = 0
while p < effN {
    dr = r[p] - meanR
    dg = rng[p] - meanG
    varR := varR + dr * dr
    varG := varG + dg * dg
    p := p + 1
}
varR := varR / effN
varG := varG / effN
stdR = sqrt(varR + 0.000000001)
stdG = sqrt(varG + 0.000000001)
if stdR < 0.000000001 { stdR := 0.000000001 }
if stdG < 0.000000001 { stdG := 0.000000001 }

maxCand = neighbourPool
if bar_index - featureLookback - 2 < maxCand { maxCand := bar_index - featureLookback - 2 }
if maxCand < 1 { maxCand := 1 }
ready = bar_index > featureLookback + 10 and maxCand >= k

marginVal = warmM
disVal = warmD
bullVotes = bullCache
bearVotes = bearCache

if ready {
    bestDist = array()
    bestLab = array()
    m = 0
    while m < k {
        array.push(bestDist, 999999.0)
        array.push(bestLab, 0)
        m := m + 1
    }
    cand = 1
    while cand <= maxCand {
        dist = 0.0
        f = 0
        while f < featureLookback {
            drf = (r[f] - r[cand + f]) / stdR
            dgf = (rng[f] - rng[cand + f]) / stdG
            dist := dist + drf * drf + dgf * dgf
            f := f + 1
        }
        insertIdx = -1
        m = 0
        while m < k {
            if dist < bestDist[m] {
                insertIdx := m
                m := k
            }
            m := m + 1
        }
        if insertIdx >= 0 {
            lab = -1
            if close[cand - 1] > close[cand] { lab := 1 }
            m = k - 1
            while m > insertIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                m := m - 1
            }
            array.set(bestDist, insertIdx, dist)
            array.set(bestLab, insertIdx, lab)
        }
        cand := cand + 1
    }
    nbull = 0
    nbear = 0
    m = 0
    while m < k {
        if bestDist[m] < 999999.0 {
            if bestLab[m] == 1 { nbull := nbull + 1 }
            else { nbear := nbear + 1 }
        }
        m := m + 1
    }
    bullVotes := nbull
    bearVotes := nbear
    bullCache := nbull
    bearCache := nbear
    tot = nbull + nbear
    if tot > 0 {
        marginVal := (nbull - nbear) / tot
        disVal := 1.0 - abs(marginVal)
        warmM := marginVal
        warmD := disVal
    } else {
        marginVal := warmM
        disVal := warmD
    }
} else {
    bullVotes := bullCache
    bearVotes := bearCache
    marginVal := warmM
    disVal := warmD
}

bullState = ready and marginVal > marginThreshold and disVal < disagreementThreshold
bearState = ready and marginVal < 0 - marginThreshold and disVal < disagreementThreshold
buySig = bullState and not bullState[1]
sellSig = bearState and not bearState[1]

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize * 1.0, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", markerSize * 1.0, 2, "separate")
}

marginChan = marginVal * 100 + r * 50 + (close - open) / close * 10
disagreeChan = disVal * 100 + rng * 200 + (high - close) / close * 10

plot(marginVal, "Vote Margin M", "#22cc88", 2, "separate")
plot(disVal, "Disagreement D", "#b48cff", 2, "separate")
hline(marginThreshold, "#22cc88", "separate")
hline(disagreementThreshold, "#b48cff", "separate")
plot3d(marginChan, "Vote Margin Channel", "bars3d", "#22cc88", "separate")
plot3d(disagreeChan, "Disagreement Channel", "scatter", "#b48cff", "separate", 1)

numBins = input(24, "Rows / Bins", 10, 48, 1)
vaPercent = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(60, "Session Length Bars", 20, 200, 5)
showTerrain = input(true, "Show 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Visible session range ─────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
binH = rng / numBins

// ─── Fresh volume-at-price bins rebuilt every bar ─────
binVol = array()
i = 0
while i < numBins {
    array.push(binVol, 0.0)
    i := i + 1
}
k = 0
while k < sessLen {
    c = close[k]
    v = volume[k]
    idx = floor((c - ll) / rng * numBins)
    if idx < 0 {
        idx := 0
    }
    if idx > numBins - 1 {
        idx := numBins - 1
    }
    array.set(binVol, idx, array.get(binVol, idx) + v)
    k := k + 1
}
totalVol = array.sum(binVol)

// ─── Point of control = max-volume bin ─────────────────
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < numBins {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) / numBins * rng
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVal / totalVol
}

// ─── Value area: expand from POC ───────────────────────
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPercent / 100
guard = 0
while accum < target and guard < numBins {
    leftVal = 0 - 1.0
    if vaLow > 0 {
        leftVal := array.get(binVol, vaLow - 1)
    }
    rightVal = 0 - 1.0
    if vaHigh < numBins - 1 {
        rightVal := array.get(binVol, vaHigh + 1)
    }
    if rightVal >= leftVal and vaHigh < numBins - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / numBins * rng
valPrice = ll + vaLow / numBins * rng
vaMid = (vahPrice + valPrice) / 2
insideVA = close >= valPrice and close <= vahPrice

// ─── Signals: price leaving value ─────────────────────
buySig = close[1] <= vahPrice and close > vahPrice
sellSig = close[1] >= valPrice and close < valPrice

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d")
}

// ─── 2D: same information when 3D is off ───────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(vaMid, "Value Mid", "#8888ff", 1)
fill(vahPrice, valPrice, "rgba(136,140,255,0.12)")
box.new(bar_index - sessLen + 1, vahPrice, bar_index, valPrice, "#8888ff", "rgba(136,140,255,0.10)", 1, "valuebox")

// ─── 3D: value terrain + labelled POC rail + boundary rails ──
plot3d(pocPrice, "Value Terrain", "surface", "#8888ff", "3d", 0)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)
plot3d(valPrice, "VAL Rail", "line3d", "#ff4477", "3d", 2)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")
if buySig {
    bgcolor("rgba(34,204,136,0.06)")
}
if sellSig {
    bgcolor("rgba(255,68,119,0.06)")
}

// FIX 1: var lvl = highest(high,20) froze at bar 0 -> plain lvl = highest(high,lvlLen) recomputed every bar.
// FIX 2: close[-1] peeks one bar into the future -> close (no lookahead) for breakout close > lvl.
// FIX 3: plotshape(true,low,"Buy",shape.triangleup,color.green) is Pine -> Oak plotshape(bar_index,price,title,style,color) with quoted style/hex.
// FIX 4: oscillator RSI in pane="3d" renders spiky forest over candles -> pane="separate" per PANE LAW.
lvlLen = input(20, "Level Length", 1, 200, 1)
rsiLen = input(14, "RSI Length", 2, 100, 1)
osLevel = input(30, "Oversold Level", 2, 50, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

lvl = highest(high, lvlLen)
r = rsi(close, rsiLen)

buySig = close > lvl
osSig = crossover(r, osLevel)

if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
  plotshape_3d(bar_index, r, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
  plotshape_3d(bar_index, r, "OS", "coneup", "#22cc88", markerSize, 1, "separate")
}

plot(lvl, "Level", "#ffcc33", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

baseFlow = input(80, "Base Flow PSI", 0, 300, 1)
flowGain = input(1.0, "Flow Price Gain", 0, 2, 0.1)
critThresh = input(150, "Critical Threshold", 50, 300, 1)
spinFactor = input(1.0, "Spin Factor", 0.1, 5, 0.1)
ringCountIn = input(3, "Ring Count", 1, 5, 1)
ringSpeed = input(2.0, "Ring Expansion Speed", 0.1, 10, 0.1)
ringMax = input(5.0, "Ring Max Radius", 1, 10, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

lo50 = lowest(low, 50)
hi50 = highest(high, 50)
rng = hi50 - lo50 + 0.000001
priceNorm = (close - lo50) / rng * 100
flowPsi = baseFlow + priceNorm * flowGain
spinRaw = spinFactor * flowPsi
overState = flowPsi > critThresh
spinSpeed = overState ? 0 : spinRaw

var rotY = 0.0
var r0 = 1.0
var r1 = 2.33
var r2 = 3.66

if overState {
    rotY := rotY
} else {
    rotY := rotY + spinSpeed * 0.05
}

if overState {
    r0 := r0 + ringSpeed * 0.2
    r1 := r1 + ringSpeed * 0.2
    r2 := r2 + ringSpeed * 0.2
    if r0 > ringMax {
        r0 := 1.0
    }
    if r1 > ringMax {
        r1 := 1.0
    }
    if r2 > ringMax {
        r2 := 1.0
    }
} else {
    r0 := 1.0
    r1 := 1.0 + priceNorm * 0.005
    r2 := 1.0 + priceNorm * 0.01
}

ringAvg = (r0 + r1 + r2) / 3
ringAvgDisp = ringAvg + priceNorm * 0.01
discAngle = rotY + close * 0.01

sellSig = crossover(flowPsi, critThresh)
buySig = crossunder(flowPsi, critThresh)

if sellSig {
    plotshape(bar_index, high, "OVERPRESSURE", "triangledown", "#ff4477")
}

if buySig {
    plotshape(bar_index, low, "Reset", "triangleup", "#22cc88")
}

if sellSig {
    plotshape_3d(bar_index, high, "OVERPRESSURE", "conedown", "#ff4477", markerSize, 1, "separate")
}

if buySig {
    plotshape_3d(bar_index, low, "Reset", "coneup", "#22cc88", markerSize, 1, "separate")
}

if sellSig {
    label3d(bar_index, high, "OVERPRESSURE", "#ff4477", 2, 1, "separate")
}

plot(flowPsi, "Flow PSI", "#22aaff", 2, "separate")
plot(spinSpeed, "Spin Speed", "#ffcc33", 1, "separate")
plot(ringAvgDisp, "Ring Radius", "#ff4477", 1, "separate")
hline(critThresh, "#ff4477", "separate")
plot3d(spinSpeed, "Disc Spin", "torus", "#22aaff", "separate", 0)
plot3d(ringAvgDisp, "Shockwave Rings", "trail", "#ff4477", "separate", 1)
